"use strict";
const fs = require("node:fs");
const path = require("node:path");
const shout = require("shout");

exports.greet = (who) => shout(`hello, ${who}`);
exports.fromData = () => fs.readFileSync(path.join(__dirname, "data", "message.txt"), "utf8").trim();
exports.byName = (name, text) => require(name)(text);
